"""Self-contained Japanese viewer for saved Starship reference-model studies.

The viewer draws recorded numerical states, never interpolated observations.
It does not infer a successful mission, flight validation or satellite service
from a trajectory. No network request or third-party rendering library is used.
"""

from __future__ import annotations

import json
import math
from bisect import bisect_left
from pathlib import Path
from typing import Any

from .starship_entry_diagnostics import diagnose_entry


def _cg_export(run: dict[str, Any]) -> dict[str, Any]:
    """Keep an independent, dense CG track: chart thinning is unsafe for rendezvous views."""
    tracks, commands, heat = {}, {}, {}
    for body_id in ("ship", "booster"):
        states = {}
        controls = []

        def append_command(start, end, values):
            if end <= start:
                return
            if controls and controls[-1][1] == start and controls[-1][2:] == values:
                controls[-1][1] = end
            else:
                controls.append([start, end, *values])

        for record in run.get("step_records", {}).get(body_id, []):
            for state in (record["before"], record["after"]):
                states[state["time_s"]] = [state["time_s"], *state["r"], *state["v"]]
            c = record["control"]
            values = [record["phase"], record["engine_count"],
                      record["vehicle"]["max_thrust_n"] * c["throttle"],
                      record["alpha_deg"], math.degrees(c["bank_rad"]),
                      *c["thrust_direction_eci"], c["throttle"]]
            start, end = record["before"]["time_s"], record["after"]["time_s"]
            if values[2] > 0:
                fuel_time = record["before"]["propellant_kg"] * record["vehicle"]["isp_s"] * 9.80665 / values[2]
                cutoff = min(end, start + fuel_time)
                append_command(start, cutoff, values)
                if cutoff < end:
                    off = list(values)
                    off[1], off[2], off[-1] = 0, 0, 0
                    append_command(cutoff, end, off)
            else:
                append_command(start, end, values)
        if not states:
            for s in run.get("traces", {}).get(body_id, []):
                states[s["time_s"]] = [s["time_s"], *(s[f"{a}_m"] for a in "xyz"), *(s[f"v{a}_mps"] for a in "xyz")]
        tracks[body_id] = [states[t] for t in sorted(states)]
        commands[body_id] = controls
        heat[body_id] = [[s["time_s"], s.get("heat_rate_w_m2", 0)]
                         for s in run.get("traces", {}).get(body_id, [])]
    for body_id, samples in run.get("traces", {}).get("satellites", {}).items():
        kept = []
        for i, sample in enumerate(samples):
            # Preserve the first two minutes in full for close release views.
            # Thereafter keep <=60 s brackets independently of the chart budget.
            if (not kept or i == len(samples) - 1
                    or sample["time_s"] <= samples[0]["time_s"] + 120
                    or (i + 1 < len(samples) and samples[i + 1]["time_s"] - kept[-1][0] > 60)):
                kept.append([sample["time_s"], *(sample[f"{a}_m"] for a in "xyz"), *(sample[f"v{a}_mps"] for a in "xyz")])
        tracks[body_id] = kept
    return {"tracks": tracks, "commands": commands, "heat": heat,
            "position_interpolation": "cubic Hermite from recorded ECI positions and velocities; display only",
            "frame": "right handed local East, Up, minus North at focus; metres",
            "attitude": "prescribed display orientation; no integrated angular dynamics",
            "satellite_maximum_bracket_s": 60,
            "source": "raw step records for vehicle states/commands and raw passive satellite samples"}


def build_report(study: dict[str, Any]) -> str:
    """Return an offline display export and diagnostics from unthinned source records."""
    if not isinstance(study, dict):
        raise ValueError("The report requires a saved study object")
    for run in study.get("runs", []):
        traces = run.get("traces", {})
        for name, trace in traces.items():
            series = trace.values() if name == "satellites" and isinstance(trace, dict) else [trace]
            for samples in series:
                if not isinstance(samples, list):
                    continue
                previous = -math.inf
                for sample in samples:
                    values = [sample.get(key) for key in ("time_s", "x_m", "y_m", "z_m")]
                    if any(isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value) for value in values):
                        raise ValueError(f"{name}: non-finite recorded time or position")
                    if values[0] <= previous:
                        raise ValueError(f"{name}: sample times must increase strictly")
                    previous = values[0]
    display_study = dict(study)
    display_study["runs"] = []
    removed = 0
    def count_steps(value: Any) -> int:
        if isinstance(value, list):
            return len(value)
        if isinstance(value, dict):
            return sum(count_steps(child) for child in value.values())
        return 0

    for original_run in study.get("runs", []):
        run = {key: value for key, value in original_run.items() if key not in ("step_records", "integration_steps")}
        removed += count_steps(original_run.get("step_records")) + count_steps(original_run.get("integration_steps"))
        run["traces"] = dict(original_run.get("traces", {}))
        if isinstance(run["traces"].get("satellites"), dict):
            run["traces"]["satellites"] = dict(run["traces"]["satellites"])
        display_study["runs"].append(run)
    counts: list[dict[str, Any]] = []
    display_fields = {
        "time_s", "x_m", "y_m", "z_m", "vx_mps", "vy_mps", "vz_mps",
        "altitude_m", "speed_mps", "propellant_mass_kg", "phase", "engine_count",
        "throttle", "alpha_deg", "bank_deg", "dynamic_pressure_pa", "heat_rate_w_m2",
        "applied_thrust_n", "thrust_n", "interval_applied_thrust_n", "lat_deg", "lon_deg",
    }
    trace_refs: list[tuple[dict[str, Any], str, list[float], dict[str, Any]]] = []
    observed_times = [p["time_s"] for p in study.get("observations", []) if isinstance(p, dict) and isinstance(p.get("time_s"), (int, float))]
    for run in display_study.get("runs", []):
        event_times = [e.get("time_s") for e in run.get("events", []) if isinstance(e, dict) and isinstance(e.get("time_s"), (int, float))]
        for name, trace in run.get("traces", {}).items():
            series = trace.items() if name == "satellites" and isinstance(trace, dict) else [(name, trace)]
            for body_id, samples in series:
                if not isinstance(samples, list) or not samples:
                    continue
                maximum = 1600 if name == "ship" else 400 if name == "booster" else 100
                original_count = len(samples)
                protected_times = event_times + observed_times if name == "ship" else event_times if name == "booster" else []
                if original_count > maximum:
                    times = [s["time_s"] for s in samples]
                    keep = {0, original_count - 1}
                    keep.update(round(i * (original_count - 1) / (maximum - 1)) for i in range(maximum))
                    for time in protected_times:
                        index = bisect_left(times, time)
                        keep.update(i for i in (index - 1, index) if 0 <= i < original_count)
                    for i in range(1, original_count):
                        if samples[i].get("phase") != samples[i - 1].get("phase"):
                            keep.update((i - 1, i))
                    selected = [samples[i] for i in sorted(keep)]
                    if name == "satellites":
                        trace[body_id] = selected
                    else:
                        run["traces"][name] = selected
                else:
                    selected = samples
                selected = [{key: value for key, value in sample.items() if key in display_fields} for sample in selected]
                container = trace if name == "satellites" else run["traces"]
                container[body_id] = selected
                count = {"scenario": run.get("scenario"), "body_id": body_id, "raw_samples": original_count, "display_samples": len(selected)}
                counts.append(count)
                trace_refs.append((container, body_id, protected_times, count))
    # A bounded display export remains usable locally even when raw integration
    # records are hundreds of megabytes. Source JSON retains complete evidence.
    while len(json.dumps(display_study, ensure_ascii=False, separators=(",", ":")).encode("utf-8")) > 3_000_000:
        reduced = False
        for container, body_id, protected_times, count in trace_refs:
            samples = container[body_id]
            if len(samples) <= 24:
                continue
            keep = {0, len(samples) - 1, *range(0, len(samples), 2)}
            times = [sample["time_s"] for sample in samples]
            for time in protected_times:
                index = bisect_left(times, time)
                keep.update(i for i in (index - 1, index) if 0 <= i < len(samples))
            for i in range(1, len(samples)):
                if samples[i].get("phase") != samples[i - 1].get("phase"):
                    keep.update((i - 1, i))
            if len(keep) < len(samples):
                reduced = True
                container[body_id] = [samples[i] for i in sorted(keep)]
                count["display_samples"] = len(keep)
        if not reduced:
            break
    display_study["report_display_export"] = {
        "all_telemetry_samples_retained": all(c["raw_samples"] == c["display_samples"] for c in counts),
        "sample_counts": counts,
        "display_fields": sorted(display_fields),
        "retained": "first, last, event brackets, observation brackets, phase transitions; evenly spaced display samples otherwise",
        "integration_step_records_omitted": removed,
        "full_evidence_json": "study.json",
        "display_only_not_full_evidence": True,
    }
    for displayed, original in zip(display_study["runs"], study.get("runs", [])):
        displayed["cg_replay"] = _cg_export(original)
    display_study["report_display_export"]["cg_tracks_separate_from_chart_thinning"] = True
    # Post-hoc diagnostics are calculated from original ship samples, never
    # chart-thinned tracks. They do not modify the frozen study or its verdict.
    reference = study.get("public_reference") or {"observations": study.get("observations", [])}
    display_study["entry_diagnostics"] = [
        diagnose_entry(run, reference) for run in study.get("runs", [])
    ]
    encoded = json.dumps(display_study, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    encoded = encoded.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    assets = Path(__file__).parent / "assets"
    scripts = "\n".join((assets / name).read_text() for name in (
        "starship_cg_models.js", "starship_cg_renderer.js", "starship_cg_replay.js"))
    # Repository-owned scripts are inlined so the exported HTML also works offline.
    return _HTML.replace("__CG_SCRIPTS__", scripts.replace("</script", "<\\/script")).replace("__STUDY_JSON__", encoded)


